import { isFinished } from './meson.js'

/**
 * @typedef {{n: number, swapId: string, message: import('discord.js').Message, latest: object, processing?: import('discord.js').Message|null, support?: import('discord.js').Message|null, outcome?: import('discord.js').Message}} SwapEntry
 *   `processing` is the swap's ⏳ reply while it is up (deleted with the closing message); `support` is its 🔎 reply while the team has to step in (deleted when the swap moves again or finishes); `outcome` is its ✅ / ↩️ closing message. All are kept so a later swap can renumber them and drop "closed soon" (syncFollowUps in watch.js).
 * @typedef {{
 *   admitted: Set<string>,    // message IDs already taken in, so one seen both live and in recovery is handled once
 *   botMessagesSeen: number,  // other bots' messages read so far (capped by AUTO_SCAN_MESSAGES)
 *   known: Set<string>,       // lowercased IDs/hashes of swaps already shown
 *   swaps: SwapEntry[],       // in posting order; entry.n is its serial number
 *   addresses: Set<string>,   // lowercased wallet addresses already listed
 *   queue: Promise<void>,     // messages are handled one at a time per ticket
 * }} Ticket
 */

// =============================================================================
//   State
// =============================================================================

/**
 * Every ticket the bot has seen since it started, by channel ID.
 * @type {Map<string, Ticket>}
 */
const tickets = new Map()

/**
 * The ticket for a channel, created empty on first use.
 * @returns {Ticket}
 */
export function getTicket (channelId) {
  let t = tickets.get(channelId)
  if (!t) {
    t = { admitted: new Set(), botMessagesSeen: 0, known: new Set(), swaps: [], addresses: new Set(), queue: Promise.resolve() }
    tickets.set(channelId, t)
  }
  return t
}

/** Drop a ticket's memory — called when its channel is deleted. */
export function forgetTicket (channelId) {
  tickets.delete(channelId)
}

// =============================================================================
//   Helpers
// =============================================================================

/** Record every identifier a user might paste for this swap. */
export function rememberSwap (t, swap) {
  for (const v of [swap.swapId, swap.encoded, ...swap.events.map((e) => e.hash)]) {
    if (v) t.known.add(String(v).toLowerCase())
  }
}

/** Serial number to show, or null while the ticket has just the one swap. */
export const serialOf = (t, entry) => (t.swaps.length > 1 ? entry.n : null)

/**
 * Options for buildOutcomeMessage.
 * "Ticket will be closed soon" is only added once every *other* swap in the ticket is finished too (Done, Released or Cancelled) — an Expired or Failed one still needs following up — and already has its closing message, so when several finish together (while the bot was down) only the last one posted says it. (syncFollowUps never adds it to an earlier closing message, only removes it.)
 */
export const outcomeOpts = (t, entry) => ({
  serial: serialOf(t, entry),
  closingSoon: t.swaps.every((e) => e === entry || (isFinished(e.latest.status) && e.outcome)),
})
